cards=[]
c=compact('future_control','未来世界主宰／控制中心','未来世界的控制中心是小机械人统治体系的最高层，命令沿机械层级下达，把幸存的人类和其他生命分门别类当作玩具。陶格一家从未来逃到现代，仍发现逃亡本身也可以是被设计的玩法；他们身体的年龄与外形都受制于这个系统，而非获得了自己的永生能力。到《圈套》，未来发生未明灾变，小机械人的作用迅速衰退，玩具一家同时急剧衰老，两个低级机械人甚至轻触便散成微粒。陶格临终进一步揭示，主宰曾通过逆转装置回到遥远过去，改变人类遗传密码，让智慧、历史冲突和残酷事件朝着其娱乐需求发展。这是小说中由知情受害者提供的解释，并非现实人类史的陈述；也不能把主宰类比编剧的说法升级成能修改作品作者的叙事权能。最终陶格说主宰已经完了，但没有给出灭亡原因，也没有证明它消亡后人类便夺回未来。卡片保留一个把生命当作可观察、可分类、可操纵对象的统治逻辑，以及其对底层设备和时间设施的依赖。若在新场景中恢复到最后可运作状态，必须明确这是部署改编，不能让已经瓦解的系统在原作终局仍随叫随到。','《圈套》末陶格证言未来主宰已经结束，现世低级设备失能解体；终结原因未知','反派','以受控生命及历史变化获取娱乐与秩序，而不是尊重被控制者的自由','借分级系统观察、分类与安排，倾向把对象的逃避也纳入游戏','控制链失稳时会失去年龄维持和远程玩具管理，不能凭自称主宰取消故障','它能操纵大量条件，却仍是会结束的故事内系统；科技影响历史不等于超越故事',[ab('分级玩具控制网络','由控制中心经不同层次机械人管理生物，维持受控年龄形态与行动安排','需正常系统与执行端；088已衰败，低级执行端黄光笼也可漏失目标',kind='基础设施'),ab('逆时与遗传历史安排','据陶格证言，经逆转装置进入遥远过去，对人类遗传密码和演化条件做安排','使用设施和长线布置；不是口头改写任意已经发生的事件，不保证跨世界适用',kind='高科技')],[ev('088',98,137,'玩具一家受未来系统控制与年龄状态'),ev('088',2173,2194,'能力衰退、驾车及黄光失控'),ev('088',2366,2414,'小机械人解体与控制层级'),ev('088',2559,2599,'逆时布置解释'),ev('088',3081,3125,'主宰结束与遗传密码圈套终局')],profile='expert',aliases=['未来世界控制中心'])
rate(c,[1,4,9,7,8,6],neg=(3,4,2),tier='准神',reason='历史能力是依时间设施与分级网络运作的广域长线控制，末期系统结束；分数描述显式恢复部署，不能把社会历史规模直接当爆炸范围',mastery='基本掌握')
