cards.append(compact('chen_anan_original','陈安安（原本人）','陈安安原是小商人夫妇珍爱的幼女，生活富足而活泼，身体突发高烧后脑部受到严重损伤，被医生判断为没有知觉、仍能生长的状态。父母不肯放弃，寻医、陪护和求神，希望有一天再听见女儿说话。后来这个身体忽然醒来，说出陌生法语并坚持寻找卫斯理，父母以为她康复，实际上是来自未来的唐娜进入了她的脑部。唐娜借她的身体与温宝裕去寻找家人，离开后，小女孩再次没有反应。温宝裕急于向家长交代，试着招魂，终局又有另一组记忆进入身体，后来确认属于江湖旧人黄皓。这些事不能写成原本的陈安安学会外语、获得未来记忆或老江湖本领：身体的连续并不等于人格的连续。她本人的意识有没有继续存在、原有记忆如何、能否恢复，文本没有给出确定答案。因此这张卡保存受害中心本人的身份与边界，避免知识库只留下占据者而把孩子抹去。需要她参与互动时，采用明确标注的病前可行动形态，已知人格只限幼年活泼、受宠及家庭经验，不替她编造对全部占据事件的第一人称记忆。','原本人意识受损，未证实恢复；身体后由唐娜短暂使用、再由黄皓占据，须与两名占据者区分','主角','作为原本人保有被照顾与表达自身意愿的地位','只按病前幼儿经验理解家人与新事物，不具占据者的知识','被成人争论或陌生安排包围时可请求熟悉照护者帮助，不能被要求负责其他灵魂的行为','同一身体的后续表现不自动归属于原本人格',[ab('幼儿日常能力','病前有普通儿童的语言、活动和对家人依赖','终局原本人意识受损，无独立可控超常能力；其他灵魂的知识与技能不转移给她')],[ev('088',1688,1718,'病前家庭、发烧脑损伤与所谓苏醒'),ev('088',1920,1955,'法语和唐娜身份的证据'),ev('088',2220,2236,'唐娜离开后失去反应'),ev('088',3116,3152,'新灵魂进入身体而身份未明'),ev('096',776,789,'后续明确身体已非原本女孩人格')],profile='ordinary'))
cards[-1]['version']['deployment']='原作终局不主张原人格已经康复。若需独立互动，明确恢复病前可行动幼儿形态，仅有本人已知记忆；与占据同一身体的唐娜或黄皓形态互斥。'
