for ident,name,part in [('chen_anan_father','陈安安的父亲','他作为生意略有成就的小商人，能为女儿请来各地医生，安排条件优越的疗养院。叙述病情时，他努力保持条理，却仍会流泪，看到女儿醒来又兴奋得讥笑曾断言无望的医生。'),('chen_anan_mother','陈安安的母亲','她把陪伴女儿当作生活中心，搬到病房，寻访被认为灵验的神佛。女儿醒来使她狂喜，却也增强了不肯放手的心情，甚至希望以找不到卫斯理为由阻止孩子见陌生人。后来在餐厅，她又当众大声教导礼仪，没有看出孩子身体内已是另一人格。')]:
 bio=name+'没有在故事中留下独立姓名。'+part+'陈安安高烧后失去知觉，夫妇承受巨大打击，始终不肯把孩子当成可以放弃的病人；然而当唐娜进入身体，他们只从会说话、会活动判断康复，并不知道人格已经不同。温宝裕把孩子带走，他们报警寻找，既有真实的担忧，也把责任强加给卫斯理。铁天音透露温宝裕能够动用陶氏基金会资源后，夫妇态度显著缓和，还乐见温妈妈提出将来婚配的保证。这显示亲情与攀附商业地位的欲望可以同时存在，不宜只写成无私照护者或完全不爱女儿的势利人。终局，外人交还的是能够行动的身体，他们仍相信自己的家庭恢复完整；女儿原本人意识是否回来没有获得确认。卡片的行动中心是家长的判断与责任，而不是继承唐娜、黄皓或医师的超常能力。'
 cards.append(compact(ident,name,bio,'仍把占据女儿身体者视为自己的孩子，未明白人格更替；家庭物质条件并未因此失去',['重要配角','阶段性对立者'],'照顾女儿、保全家庭，同时重视社会地位与商业机会','以家长身份询问安排，在可负担时购买专业服务','孩子下落不明时会寻亲友、报警与施压；听到显赫身份可能过早放下警戒','对孩子的关心不能替代核实事实，财富和身份不保证安全',[ab('家庭照护与社会求助','有经济条件安排护理、就医、亲友和警方帮助','依资源与机构实际响应；没有医术、读心或可直接恢复脑损伤的能力')],[ev('088',1684,1782,'病情、陪护、孩子要求与父母选择'),ev('088',1838,1860,'对卫施压寻找'),ev('088',1981,2019,'报警为拐带'),ev('088',2617,2633,'得知基金会身份后的态度变化'),ev('096',773,825,'母亲在餐厅照顾并管束被占据身体的孩子')],profile='expert'))
save(cards)
